@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2">
    @for (int i = 1; i <= 5; i++)
    {
        var starValue = i;
        <span style="cursor: pointer; font-size: 1.5rem; color: @(starValue <= _selectedRating ? "#ffc107" : "#e0e0e0")"
              @onclick="() => Rate(starValue)">&#9733;</span>
    }
    @if (_submitted)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }
</div>
<div class="text-muted small mt-1">
    Average: @CurrentRating.ToString("F1") / 5
</div>

@code {
    [Parameter]
    public string RecipeSlug { get; set; } = string.Empty;

    [Parameter]
    public double CurrentRating { get; set; }

    private int _selectedRating;
    private bool _submitted;

    private void Rate(int rating)
    {
        _selectedRating = rating;
        RecipeService.RateRecipe(RecipeSlug, rating);
        var recipe = RecipeService.GetBySlug(string.Empty, string.Empty);
        // Refresh the current rating from service
        CurrentRating = GetUpdatedRating();
        _submitted = true;
    }

    private double GetUpdatedRating()
    {
        // Search all categories for the recipe
        foreach (var category in RecipeService.GetCategories())
        {
            var recipe = RecipeService.GetBySlug(category, RecipeSlug);
            if (recipe != null) return recipe.AverageRating;
        }
        return CurrentRating;
    }
}

@page "/recipes/{Category}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>@Category Recipes - RecipeShare</PageTitle>

<h1>@Category Recipes</h1>

@if (_recipes.Any())
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            @recipe.Ingredients.Count ingredients &bull; @recipe.Steps.Count steps
                        </p>
                        <div class="mb-2">
                            <span style="color: #ffc107;">&#9733;</span> @recipe.AverageRating.ToString("F1")
                        </div>
                        <a href="/recipes/@Category/@recipe.Slug" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p class="text-muted">No recipes found in this category.</p>
}

<a href="/" class="btn btn-outline-secondary mt-3">&larr; Back to Categories</a>

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private List<Recipe> _recipes = new();

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetByCategory(Category);
    }
}

