@rendermode InteractiveServer
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted successfully!</h4>
        <p>Your recipe "<strong>@_title</strong>" has been added to @_category.</p>
        <a href="/recipes/@_category" class="btn btn-primary">View Category</a>
    </div>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title *</label>
            <InputText id="title" class="form-control" @bind-Value="_title" required />
            @if (_errors.ContainsKey("title"))
            {
                <div class="text-danger small">@_errors["title"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category *</label>
            <InputSelect id="category" class="form-select" @bind-Value="_category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
            @if (_errors.ContainsKey("category"))
            {
                <div class="text-danger small">@_errors["category"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients * (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_ingredients" />
            @if (_errors.ContainsKey("ingredients"))
            {
                <div class="text-danger small">@_errors["ingredients"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps * (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_steps" />
            @if (_errors.ContainsKey("steps"))
            {
                <div class="text-danger small">@_errors["steps"]</div>
            }
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private string _title = string.Empty;
    private string _category = string.Empty;
    private string _ingredients = string.Empty;
    private string _steps = string.Empty;
    private bool _submitted;
    private Dictionary<string, string> _errors = new();

    private void HandleSubmit()
    {
        _errors.Clear();

        if (string.IsNullOrWhiteSpace(_title))
            _errors["title"] = "Title is required.";
        if (string.IsNullOrWhiteSpace(_category))
            _errors["category"] = "Category is required.";
        if (string.IsNullOrWhiteSpace(_ingredients))
            _errors["ingredients"] = "Ingredients are required.";
        if (string.IsNullOrWhiteSpace(_steps))
            _errors["steps"] = "Steps are required.";

        if (_errors.Any()) return;

        var slug = _title.ToLower().Replace(" ", "-").Replace("'", "");
        var recipe = new Recipe
        {
            Title = _title,
            Slug = slug,
            Category = _category,
            Ingredients = _ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = _steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            AverageRating = 0,
            RatingCount = 0
        };

        RecipeService.AddRecipe(recipe);
        _submitted = true;
    }
}

