    private string _ingredients = string.Empty;
    private string _steps = string.Empty;
    private bool _submitted;
    private Dictionary<string, string> _errors = new();

    private void HandleSubmit()
    {
        _errors.Clear();

        if (string.IsNullOrWhiteSpace(_title))
            _errors["title"] = "Title is required.";
        if (string.IsNullOrWhiteSpace(_category))
            _errors["category"] = "Category is required.";
        if (string.IsNullOrWhiteSpace(_ingredients))
            _errors["ingredients"] = "Ingredients are required.";
        if (string.IsNullOrWhiteSpace(_steps))
            _errors["steps"] = "Steps are required.";

        if (_errors.Any()) return;

        var slug = _title.ToLower().Replace(" ", "-").Replace("'", "");
        var recipe = new Recipe
        {
            Title = _title,
            Slug = slug,
            Category = _category,
            Ingredients = _ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = _steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            AverageRating = 0,
            RatingCount = 0
        };

        RecipeService.AddRecipe(recipe);
        _submitted = true;
    }
}

